-- 1. Clean up legacy aliases, disease management members, and demo concepts
delete from RHN_BD_CONCEPT_ALIAS where ID_CONCEPT in (select ID_CONCEPT from RHN_BD_CONCEPT where ID_CODE_SYSTEM = 362387869795001);
delete from RHN_HPL_DISEASE_MGMT_MEMBER where ID_CONCEPT in (select ID_CONCEPT from RHN_BD_CONCEPT where ID_CODE_SYSTEM = 362387869795001);
delete from RHN_BD_CONCEPT where ID_CODE_SYSTEM = 362387869795001;

-- 2. Update Code System metadata to National Healthcare Security ICD-10 v2.0
update RHN_BD_CODE_SYSTEM
set NA_CODE_SYSTEM = 'ICD-10 疾病分类（国家医保版 2.0）',
    PUBLSHR = '国家医疗保障局',
    DES_CODE_SYSTEM = '国家医疗保障疾病诊断分类与代码 (ICD-10 医保版 2.0)，收录国家标准章节、类目、亚目与细目全量诊断目录',
    DT_UPDATED = timestamp with time zone '2026-09-25 12:00:00+08'
where ID_CODE_SYSTEM = 362387869795001;

